<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Services\{RectorXmlImporter,LessonOccurrenceGenerator,ScheduleReplacementApplier,CurriculumScheduleBinder}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Throwable;
class ScheduleImportController extends Controller {
 public function index(){return view('admin.schedule.import',['runs'=>DB::table('import_runs as i')->leftJoin('academic_periods as p','p.id','=','i.academic_period_id')->leftJoin('academic_years as y','y.id','=','p.academic_year_id')->select('i.*','p.name as period_name','y.name as year_name')->orderByDesc('i.id')->limit(30)->get()]);}
 public function store(Request $r,RectorXmlImporter $importer,LessonOccurrenceGenerator $generator,ScheduleReplacementApplier $replacements,CurriculumScheduleBinder $binder){$r->validate(['xml'=>'required|file|max:30720','lesson_unit_mode'=>'nullable|in:lesson,pair']);$f=$r->file('xml');try{$result=$importer->import($f->getRealPath(),$f->getClientOriginalName(),$r->user()->id,$r->filled('lesson_unit_mode')?$r->string('lesson_unit_mode')->toString():null);$lessons=$generator->generate($result['period_id']);$rep=$replacements->apply($result['period_id']);$bind=$binder->bindPeriod($result['period_id'],true);DB::table('rector_exchange_runs')->insert(['academic_period_id'=>$result['period_id'],'user_id'=>$r->user()->id,'direction'=>'import','kind'=>'schedule','filename'=>$f->getClientOriginalName(),'sha256'=>hash_file('sha256',$f->getRealPath()),'status'=>'done','stats'=>json_encode(['schedule_entries'=>$result['schedule_entries'],'lessons'=>$lessons,'replacements'=>$rep['applied'],'curriculum_bound'=>$bind['bound']],JSON_UNESCAPED_UNICODE),'created_at'=>now(),'updated_at'=>now()]);$r->session()->put('academic_period_id',$result['period_id']);return back()->with('success',"Импорт завершён: {$result['year']}, ".($result['period']===1?'I':'II')." полугодие. Строк расписания: {$result['schedule_entries']}; занятий: $lessons; замен применено: {$rep['applied']}; КТП привязано: {$bind['bound']}.");}catch(Throwable $e){report($e);return back()->withErrors(['xml'=>'Ошибка импорта: '.$e->getMessage()]);}}
}
